def _finito(valor, contexto):
    try:
        numero = Decimal(valor)
    except (InvalidOperation, TypeError, ValueError) as erro:
        raise RuntimeError(
            f"ADR-003: valor inválido em {contexto}: {valor}"
        ) from erro
    if not numero.is_finite():
        raise RuntimeError(
            f"ADR-003: valor não finito em {contexto}: {valor}"
        )
    return numero


def quarentenar_e_evidenciar(apps, schema_editor):
    """Representa bloqueio sem dono e registra reservas parciais."""
    Estoque = apps.get_model("stock", "Estoque")
    Reserva = apps.get_model("stock", "ReservaEstoque")
    Bloqueio = apps.get_model("stock", "BloqueioLegado")
    Reconciliacao = apps.get_model("stock", "ReconciliacaoEstoqueLegado")
    ItemPedido = apps.get_model("sales", "ItemPedido")

    for estoque in Estoque.objects.all().iterator():
        ativas = Reserva.objects.filter(
            produto_id=estoque.produto_id,
            unidade_id=estoque.unidade_id,
            status="ativa",
        ).aggregate(total=Sum("quantidade"))["total"] or Decimal("0.00")
        bloqueada = _finito(
            estoque.quantidade_bloqueada,
            f"estoque {estoque.produto_id}/{estoque.unidade_id}",
        )
        excedente = bloqueada - _finito(
            ativas,
            f"reservas ativas {estoque.produto_id}/{estoque.unidade_id}",
        )
        if excedente < 0:
            raise RuntimeError(
                "ADR-003: bloqueio menor que reservas ativas para "
                f"produto={estoque.produto_id}, unidade={estoque.unidade_id}: "
                f"bloqueada={estoque.quantidade_bloqueada}, ativas={ativas}"
            )
        if excedente > 0:
            Bloqueio.objects.create(
                produto_id=estoque.produto_id,
                unidade_id=estoque.unidade_id,
                quantidade=excedente,
                motivo=(
                    "Bloqueio legado sem pedido identificado; "
                    "mantido em quarentena pela migração ADR-003."
                ),
            )
            Reconciliacao.objects.create(
                produto_id=estoque.produto_id,
                unidade_id=estoque.unidade_id,
                tipo="bloqueio_quarentena",
                quantidade=excedente,
                saldo_original=estoque.quantidade_bloqueada,
                detalhe={
                    "reservas_ativas": str(ativas),
                    "excedente": str(excedente),
                },
            )

    for reserva in Reserva.objects.filter(status="ativa").iterator():
        devido = ItemPedido.objects.filter(
            pedido_id=reserva.pedido_id,
            produto_id=reserva.produto_id,
        ).aggregate(total=Sum("quantidade"))["total"] or Decimal("0.00")
        devido = _finito(devido, f"itens do pedido {reserva.pedido_id}")
        if _finito(
            reserva.quantidade, f"reserva {reserva.pk}"
        ) != devido:
            Reconciliacao.objects.create(
                produto_id=reserva.produto_id,
                unidade_id=reserva.unidade_id,
                tipo="reserva_parcial",
                quantidade=abs(devido - reserva.quantidade),
                detalhe={
                    "reserva_id": reserva.pk,
                    "reservado": str(reserva.quantidade),
                    "devido": str(devido),
                    "parcial": reserva.quantidade < devido,
                },
            )


